 useEffect(()=>{const context=(document as Document&{modelContext?:{registerTool:(tool:unknown,options?:{signal:AbortSignal})=>void|Promise<void>}}).modelContext;if(!context?.registerTool)return;const abort=new AbortController();void Promise.resolve(context.registerTool({name:"search_ads",title:"Buscar anuncios",description:"Filtra anuncios visibles por búsqueda, tipo y ciudad.",inputSchema:{type:"object",properties:{query:{type:"string"},kind:{type:"string",enum:kinds},city:{type:"string",enum:["Todas las ciudades",...cities]}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input:unknown){const d=input as {query?:unknown;kind?:unknown;city?:unknown};if(d.query!==undefined&&typeof d.query!=="string")throw Error("Búsqueda inválida");if(d.kind!==undefined&&!kinds.includes(String(d.kind)))throw Error("Tipo inválido");if(d.city!==undefined&&!(["Todas las ciudades",...cities].includes(String(d.city))))throw Error("Ciudad inválida");setQuery(String(d.query??""));setKind(String(d.kind??"Todos"));setCity(String(d.city??"Todas las ciudades"));setView("explorar");return {status:"filtered"}}},{signal:abort.signal})).catch(()=>{});return()=>abort.abort()},[]);
